```lua
-- returns { "A", "B", "C", "D" }
flat = table.flatten { "A", { "B", "C", { "D" } } }
```

```lua
-- returns { "x", "y" }
table.insertflat({ "x" }, "y")

-- returns { "x", "y", "z" }
table.insertflat({ "x" }, { "y", { "z" } })
```

```lua
-- returns { "X", "Y" }
table.translate({ "A", "B", "C"}, { A = "X", C = "Y"})

-- returns { 2, 3, 4 }
table.translate({ 1, 2, 3}, function(value) return value + 1 end)
```
